function validate([transactions]) {
  if (transactions.length < 1 || transactions.length > 100000) return 'transactions needs 1 to 100000 entries.';
  for (const pair of transactions) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each transaction is a pair [cost, cashback].';
    if (pair.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'cost and cashback are integers from 0 to 10^9.';
  }
  return null;
}

