function minimumMoney(transactions) {
  let totalLoss = 0;
  let extra = 0;

  for (const [cost, cashback] of transactions) {
    if (cost > cashback) {
      totalLoss += cost - cashback;
    }
    extra = Math.max(extra, Math.min(cost, cashback));
  }
  return totalLoss + extra;
}

