function minimumMoney(transactions) {
  const n = transactions.length;
  const used = new Array(n).fill(false);
  let worst = 0;
  // Try every order; an order needs, before each step, the money already spent net plus that step's cost.
  const walk = (depth, spent, need) => {
    if (depth === n) { worst = Math.max(worst, need); return; }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = true;
      const [cost, cashback] = transactions[i];
      walk(depth + 1, spent + cost - cashback, Math.max(need, spent + cost));
      used[i] = false;
    }
  };
  walk(0, 0, 0);
  return worst;
}

