function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = rand() < 0.5 ? 1000000000 : 1000;
    return [Array.from({ length: 2000 }, () => [int(0, top), int(0, top)])];
  }
  const n = int(1, 7);
  const top = rand() < 0.3 ? 3 : 12;
  return [Array.from({ length: n }, () => [int(0, top), int(0, top)])];
}
